scenario.en:
window.addEventListener("error", (e) => report("window-error", e.error));
window.addEventListener("unhandledrejection", (e) => report("rejection", e.reason));

<ErrorBoundary onError={(err, info) => report("boundary", err, info.componentStack)}>
  <Chart />        {/* A: throws during render */}
  <SaveButton />   {/* B: onClick={() => { throw new Error("save") }} */}
  <Feed />         {/* C: useEffect(() => { (async () => { await fetch(url); })(); }, []) — fetch rejects */}
</ErrorBoundary>

scenario.ru:
// Три сбоя — три разных канала. Какой куда?
window.addEventListener("error", (e) => report("window-error", e.error));
window.addEventListener("unhandledrejection", (e) => report("rejection", e.reason));

<ErrorBoundary onError={(err, info) => report("boundary", err, info.componentStack)}>
  <Chart />        {/* A: бросает во время рендера */}
  <SaveButton />   {/* B: onClick={() => { throw new Error("save") }} */}
  <Feed />         {/* C: useEffect(() => { (async () => { await fetch(url); })(); }, []) — fetch реджектится */}
</ErrorBoundary>
